// Светофор 1
const int L1_R = 2;
const int L1_Y = 3;
const int L1_G = 4;

// Светофор 2
const int L2_R = 5;
const int L2_Y = 6;
const int L2_G = 7;

// Светофор 3
const int L3_R = 8;
const int L3_Y = 9;
const int L3_G = 10;

void setup() {
  // Настройка всех пинов как выходов
  pinMode(L1_R, OUTPUT);
  pinMode(L1_Y, OUTPUT);
  pinMode(L1_G, OUTPUT);

  pinMode(L2_R, OUTPUT);
  pinMode(L2_Y, OUTPUT);
  pinMode(L2_G, OUTPUT);

  pinMode(L3_R, OUTPUT);
  pinMode(L3_Y, OUTPUT);
  pinMode(L3_G, OUTPUT);
}

// Вспомогательная функция для установки состояния всех светофоров разом
void setLights(
  int l1r, int l1y, int l1g,
  int l2r, int l2y, int l2g,
  int l3r, int l3y, int l3g
) {
  digitalWrite(L1_R, l1r);
  digitalWrite(L1_Y, l1y);
  digitalWrite(L1_G, l1g);

  digitalWrite(L2_R, l2r);
  digitalWrite(L2_Y, l2y);
  digitalWrite(L2_G, l2g);

  digitalWrite(L3_R, l3r);
  digitalWrite(L3_Y, l3y);
  digitalWrite(L3_G, l3g);
}

void loop() {
  // Фаза 1: Все красные
  setLights(HIGH, LOW, LOW,   HIGH, LOW, LOW,   HIGH, LOW, LOW);
  delay(3000);

  // Фаза 2: Светофор 1 и 2 жёлтые, 3 красный
  setLights(LOW, HIGH, LOW,   LOW, HIGH, LOW,   HIGH, LOW, LOW);
  delay(2000);

  // Фаза 3: Светофор 1 и 2 зеленые, 3 красный
  setLights(LOW, LOW, HIGH,   LOW, LOW, HIGH,   HIGH, LOW, LOW);
  delay(5000);

  // Фаза 4: Светофор 1 зеленый, 2 мигает (имитация мигающего зеленого), 3 красный
  for(int i = 0; i < 3; i++) {
    setLights(LOW, LOW, HIGH,   LOW, LOW, HIGH,   HIGH, LOW, LOW);
    delay(300);
    setLights(LOW, LOW, HIGH,   LOW, LOW, LOW,    HIGH, LOW, LOW);
    delay(300);
  }

  // Фаза 5: Светофор 1 зеленый, 2 жёлтый, 3 красный
  setLights(LOW, LOW, HIGH,   LOW, HIGH, LOW,   HIGH, LOW, LOW);
  delay(2000);

  // Фаза 6: Светофор 1 зеленый, остальные красные
  setLights(LOW, LOW, HIGH,   HIGH, LOW, LOW,   HIGH, LOW, LOW);
  delay(4000);

  // Фаза 7: Светофор 1 мигает жёлтым, 2 красный, 3 жёлтый
  for(int i = 0; i < 3; i++) {
    setLights(LOW, HIGH, LOW,   HIGH, LOW, LOW,   LOW, HIGH, LOW);
    delay(400);
    setLights(LOW, LOW, LOW,    HIGH, LOW, LOW,   LOW, LOW, LOW);
    delay(400);
  }

  // Фаза 8: Светофор 3 зеленый, остальные красные
  setLights(HIGH, LOW, LOW,   HIGH, LOW, LOW,   LOW, LOW, HIGH);
  delay(5000);

  // Фаза 9: Светофор 3 мигает зеленым
  for(int i = 0; i < 3; i++) {
    setLights(HIGH, LOW, LOW,   HIGH, LOW, LOW,   LOW, LOW, HIGH);
    delay(300);
    setLights(HIGH, LOW, LOW,   HIGH, LOW, LOW,   HIGH, LOW, LOW);
    delay(300);
  }
}
